def _sans_remarque_ovaire(lessons):
    # Le manuel 7e C ne contient pas le tableau « greffe d’un fragment de l’ovaire » : on retire la correction.
    for l in lessons:
        l["board"] = [b for b in l["board"] if not any("fragment de l’ovaire" in x for x in b["lines"])]
    return lessons


